#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <stdexcept>
#include <algorithm>
#include <cstdint>
struct Wav{uint16_t channels;uint32_t rate;std::vector<int16_t>samples;};
uint32_t u32(const std::vector<unsigned char>&b,size_t p){if(p+4>b.size())throw std::runtime_error("truncated header");return b[p]|(uint32_t(b[p+1])<<8)|(uint32_t(b[p+2])<<16)|(uint32_t(b[p+3])<<24);}uint16_t u16(const std::vector<unsigned char>&b,size_t p){if(p+2>b.size())throw std::runtime_error("truncated format");return b[p]|(b[p+1]<<8);}
Wav read(const std::string&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("Cannot open WAV");std::vector<unsigned char>b((std::istreambuf_iterator<char>(f)),{});if(b.size()<12||std::string(b.begin(),b.begin()+4)!="RIFF"||std::string(b.begin()+8,b.begin()+12)!="WAVE")throw std::runtime_error("Not RIFF WAV");Wav w{};bool format=false,data=false;for(size_t p=12;p+8<=b.size();){auto size=u32(b,p+4);size_t start=p+8;if(size>b.size()-start)throw std::runtime_error("Truncated chunk");std::string id(b.begin()+p,b.begin()+p+4);if(id=="fmt "){if(size<16||u16(b,start)!=1||u16(b,start+14)!=16)throw std::runtime_error("Only PCM16 supported");w.channels=u16(b,start+2);w.rate=u32(b,start+4);format=true;}if(id=="data"){if(size%2)throw std::runtime_error("Odd PCM16 payload");for(size_t i=start;i<start+size;i+=2)w.samples.push_back(int16_t(u16(b,i)));data=true;}p=start+size+(size%2);}if(!format||!data||w.channels<1||w.channels>2||!w.rate||w.samples.size()%w.channels)throw std::runtime_error("Unsupported or incomplete WAV");return w;}
void put(std::ofstream&f,uint32_t n,int bytes){for(int i=0;i<bytes;i++)f.put(char(n>>(8*i)));}void save(const Wav&w,const std::string&p){std::ifstream existing(p);if(existing.good())throw std::runtime_error("Output exists; choose a new path");std::ofstream f(p,std::ios::binary);if(!f)throw std::runtime_error("Output cannot be opened");uint32_t size=w.samples.size()*2;f.write("RIFF",4);put(f,36+size,4);f.write("WAVEfmt ",8);put(f,16,4);put(f,1,2);put(f,w.channels,2);put(f,w.rate,4);put(f,w.rate*w.channels*2,4);put(f,w.channels*2,2);put(f,16,2);f.write("data",4);put(f,size,4);for(auto x:w.samples)put(f,uint16_t(x),2);if(!f)throw std::runtime_error("Write failed");}
Wav channel(const Wav&w,int c){if(c<0||c>=w.channels)throw std::runtime_error("Invalid channel");Wav o{1,w.rate,{}};for(size_t i=c;i<w.samples.size();i+=w.channels)o.samples.push_back(w.samples[i]);return o;}void reverse(Wav&w){size_t n=w.samples.size()/w.channels;for(size_t i=0;i<n/2;i++)for(int c=0;c<w.channels;c++)std::swap(w.samples[i*w.channels+c],w.samples[(n-1-i)*w.channels+c]);}
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="--self-test"){Wav w{2,8000,{1,2,3,4,5,6}};reverse(w);if(w.samples!=std::vector<int16_t>{5,6,3,4,1,2}||channel(w,1).samples!=std::vector<int16_t>{6,4,2})throw std::runtime_error("frame invariant failed");std::cout<<"Stereo frame reversal and channel extraction passed\n";return 0;}if(argc!=4)throw std::runtime_error("Usage: wav-toolkit reverse|left|right input.wav new-output.wav");auto w=read(argv[2]);std::string op=argv[1];if(op=="reverse")reverse(w);else if(op=="left"||op=="right")w=channel(w,op=="right"?1:0);else throw std::runtime_error("Unknown operation");save(w,argv[3]);std::cout<<"Wrote "<<argv[3]<<" · "<<w.channels<<" channel(s), "<<w.rate<<" Hz, "<<w.samples.size()/w.channels<<" frames\n";}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
